// @vitest-environment node
import { afterEach, beforeEach, expect, it, vi } from 'vitest'
const mocks = vi.hoisted(() => ({ create: vi.fn(), client: vi.fn() }))
vi.mock('openai', () => ({ default: class { constructor(config: unknown) { mocks.client(config) } chat = { completions: { create: mocks.create } } } }))
import { streamAnswer, type AnswerParams } from './providers'
import { callRepoModel, streamRepoModel } from '@/lib/repo/agentProviders'
const input: AnswerParams = { model: 'openrouter/anthropic/claude-fixture', system: 'Grounded', transcript: 'Call / speaker 1: Hello', context: null, history: [], question: 'Explain retries?', image: null, temperature: .2 }
async function* events(items: unknown[]) { for (const item of items) yield item }
beforeEach(() => { vi.clearAllMocks(); for (const key of ['ANTHROPIC_API_KEY','OPENAI_API_KEY','GROQ_API_KEY','COPILOT_MODEL_FAST','COPILOT_MODEL_SMART']) vi.stubEnv(key, ''); vi.stubEnv('OPENROUTER_API_KEY','test-fixture') })
afterEach(() => vi.unstubAllEnvs())
it('uses the explicit OpenRouter endpoint and model slug with no client secret or unsupported temperature', async () => {
  mocks.create.mockResolvedValue(events([{ choices: [{ delta: { content: 'Use a bounded retry budget.' }, finish_reason: 'stop' }] }]))
  expect(await new Response(streamAnswer(input)).text()).toBe('Use a bounded retry budget.')
  expect(mocks.client).toHaveBeenCalledWith(expect.objectContaining({ baseURL: 'https://openrouter.ai/api/v1', apiKey: 'test-fixture', maxRetries: 0 }))
  const request = mocks.create.mock.calls[0][0]
  expect(request.model).toBe('anthropic/claude-fixture')
  expect(request).not.toHaveProperty('temperature')
  expect(JSON.stringify(request)).not.toContain('test-fixture')
})
it.each(['length', undefined])('does not report an incomplete OpenRouter stream as complete (%s)', async reason => {
  mocks.create.mockResolvedValue(events([{ choices: [{ delta: { content: 'Partial' }, finish_reason: reason }] }]))
  await expect(new Response(streamAnswer(input)).text()).rejects.toThrow('incomplete')
})
it('routes independent repo specialists through the same adapter without disguising a failure as a second opinion', async () => {
  mocks.create.mockResolvedValue({ model: 'claude-fixture-returned', choices: [{ message: { content: 'Inspect cancellation.' }, finish_reason: 'stop' }], usage: { prompt_tokens: 50, completion_tokens: 15 } })
  const request = { model: input.model, system: input.system, evidence: 'src/order.ts:1 cancel()', signal: new AbortController().signal }
  const result = await callRepoModel(request)
  expect(result.model).toBe('claude-fixture-returned')
  expect(mocks.create.mock.calls[0][0]).toMatchObject({ model: 'anthropic/claude-fixture', max_tokens: 2200 })
  mocks.create.mockResolvedValue(events([{ model: 'returned', choices: [{ delta: { content: 'Partial' } }] }]))
  await expect((async () => { for await (const _ of streamRepoModel(request)) void _ })()).rejects.toThrow('incomplete')
})

