import { describe, it, expect } from 'vitest'
import { captureSpeakerLabel } from './speakerLabels'
import { liveTranscript } from './useInterviewRecorder'
describe('channel-scoped speaker labels', () => {
  const row = { id: 1, speaker: 0, text: 'The actual response.', isFinal: true, capturedAt: 1000 }
  it('does not confuse speaker zero on the call with speaker zero on the microphone', () => {
    const names = { 'call:0': 'Interviewer Alex', 'mic:0': 'Candidate' }
    expect(liveTranscript([row], [{ ...row, capturedAt: 1001 }], names)).toBe('Interviewer Alex (call): The actual response.\nCandidate (microphone): The actual response.')
  })
  it('retains unknown speech without inventing an identity', () => {
    expect(captureSpeakerLabel('call', { speaker: null })).toBe('Call / unknown speaker')
    expect(liveTranscript([{ ...row, speaker: null, isFinal: false }], [])).toContain('[Unfinalized transcription; verify]')
  })
})

import type { Segment } from '@/lib/transcript/store'
export type CaptureChannel = 'call' | 'mic'
export type CaptureSpeakerNames = Record<string, string>
export const captureSpeakerKey = (channel: CaptureChannel, row: Pick<Segment, 'speaker'>) => `${channel}:${row.speaker ?? 'unknown'}`
export function captureSpeakerLabel(channel: CaptureChannel, row: Pick<Segment, 'speaker' | 'name'>, names: CaptureSpeakerNames = {}): string {
  const name = names[captureSpeakerKey(channel, row)]?.trim() || row.name?.trim()
  if (name) return `${name.slice(0, 60)} (${channel === 'mic' ? 'microphone' : 'call'})`
  if (channel === 'mic') return row.speaker != null && row.speaker > 0 ? `Microphone / speaker ${row.speaker + 1}` : 'Candidate microphone'
  return row.speaker == null ? 'Call / unknown speaker' : `Call / speaker ${row.speaker + 1}`
}

